1	/* ============================================================
2	   FEATURED LOGOS — featured-logos.module.css
3	   Extracted verbatim from boldteq-v1-0.webflow.css
4	   ============================================================ */
5	
6	.section-regular {
7	  background-color: #fff;
8	  padding: 0 5%;
9	  position: relative;
10	  overflow: visible;
11	}
12	
13	.no-padding-mob {
14	  /* base — see mobile media query for override */
15	}
16	
17	.logo-mob {
18	  /* base — see mobile media query for override */
19	}
20	
21	.logo-3-title {
22	  text-align: center;
23	  flex-flow: column;
24	  justify-content: flex-start;
25	  align-items: center;
26	  max-width: 628px;
27	  margin-bottom: 20px;
28	  margin-left: auto;
29	  margin-right: auto;
30	  display: flex;
31	}
32	
33	.paragraph-x-large {
34	  margin-bottom: 0;
35	  font-size: 20px;
36	  line-height: 1.5;
37	}
38	
39	.text-color-secondary {
40	  color: #2b2b2b;
41	  font-family: 'Roobert PRO', Arial, sans-serif;
42	  font-size: 14px;
43	}
44	
45	.logo-3-carousel {
46	  justify-content: center;
47	  align-items: center;
48	  width: 100%;
49	  display: flex;
50	  overflow: hidden;
51	  -webkit-mask-image: linear-gradient(to right, #0000 0%, #000 10% 90%, #0000 100%);
52	  mask-image: linear-gradient(to right, #0000 0%, #000 10% 90%, #0000 100%);
53	}
54	
55	.logo-3-content {
56	  grid-column-gap: 24px;
57	  grid-row-gap: 24px;
58	  opacity: 1;
59	  flex-flow: row;
60	  display: flex;
61	}
62	
63	.logo-3-block {
64	  opacity: 0.4;
65	  justify-content: center;
66	  align-items: center;
67	  min-width: auto;
68	  padding: 0;
69	  display: flex;
70	}
71	
72	.logo-3-block:hover {
73	  opacity: 1;
74	}
75	
76	.logo-3-icon {
77	  /* dimension set per image */
78	}
79	
80	/* ============================================================
81	   max-width: 767px
82	   ============================================================ */
83	@media screen and (max-width: 767px) {
84	  .logo-3-block {
85	    min-width: 150px;
86	  }
87	
88	  .logo-3-content {
89	    grid-column-gap: 12px;
90	    grid-row-gap: 12px;
91	  }
92	
93	  .paragraph-x-large {
94	    font-size: 18px;
95	  }
96	}
97	
98	/* ============================================================
99	   max-width: 479px  (mobile)
100	   ============================================================ */
101	@media screen and (max-width: 479px) {
102	  .section-regular.no-padding-mob {
103	    padding-left: 0%;
104	    padding-right: 0%;
105	  }
106	
107	  .section-regular.no-padding-mob.logo-mob {
108	    padding-top: 40px;
109	  }
110	
111	  .logo-3-block {
112	    justify-content: center;
113	    align-items: center;
114	    width: auto;
115	    min-width: auto;
116	  }
117	
118	  .logo-3-title {
119	    margin-bottom: 10px;
120	  }
121	
122	  .logo-3-content {
123	    grid-column-gap: 30px;
124	    grid-row-gap: 30px;
125	    flex-flow: row;
126	    display: flex;
127	  }
128	}
